import {icon} from './icons.js';
import {tasks,quiz,math,faqs,countries} from './data.js';
import {payPage,bindPay} from './pay.js';
const staticMode=location.hostname.endsWith('.github.io');
const $=(s)=>document.querySelector(s), esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storedDemo=null;try{storedDemo=JSON.parse(localStorage.getItem('gs-demo')||'null');if(storedDemo&&(!Array.isArray(storedDemo.completed)||!Array.isArray(storedDemo.transactions)||!Array.isArray(storedDemo.pending)||!Number.isFinite(storedDemo.balance)||typeof storedDemo.name!=='string'))storedDemo=null;}catch{}
let demo=storedDemo,user=null,filter='All',search='',step=0,answers=[],playing=null;
const money=(v)=>`UGX ${Number(v).toLocaleString('en-UG')}`;
const save=()=>localStorage.setItem('gs-demo',JSON.stringify(demo));
const go=(p)=>{location.hash='/'+p;};
const button=(text,route,cls='primary')=>`<a class="btn ${cls}" href="#/${route}">${text}</a>`;
const logo=(dark=false)=>`<a href="#/" class="brand" aria-label="Glorysake home" translate="no"><img src="./assets/logo-${dark?'dark':'white'}.png" alt=""><span>glorysake<span class="brand-dot">.</span></span></a>`;
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
async function api(path,data,method){const res=await fetch('./api/'+path,{method:method||(data?'POST':'GET'),headers:{'Content-Type':'application/json'},...(data?{body:JSON.stringify(data)}:{})});let body;try{body=await res.json();}catch{throw Error('Account services need the GLORYSAKE server. Explore the demo while hosting is configured.');}if(!res.ok)throw Error(body.error||'Something went wrong. Please try again.');return body;}
function nav(){const cur=location.hash.slice(2).split('?')[0];const links=[['how-it-works','How it works'],['explore','Activities'],['pay','How to pay'],['trust','Why trust us'],['support','Help']].map(([r,t])=>`<a href="#/${r}"${cur===r?' aria-current="page"':''}>${t}</a>`).join('');return `<header class="public-header g-header"><div class="g-wrap g-nav">${logo(true)}<nav class="desktop-nav" aria-label="Main navigation">${links}</nav><div class="nav-actions">${staticMode?'':'<a class="login-link" href="#/login">Log in</a>'}<a class="g-btn g-btn-primary g-btn-sm" href="#/${staticMode?'demo':'register'}">${staticMode?'Try the demo':'Join free'}</a><button class="g-menu" aria-label="Open menu" aria-expanded="false" data-action="menu">${icon('menu')}</button></div></div><nav class="mobile-nav g-mobile-nav" hidden aria-label="Mobile navigation">${links}${staticMode?'':'<a href="#/login">Log in</a>'}</nav></header>`;}
function footer(){return `<footer class="g-footer"><div class="g-wrap g-footer-grid"><div class="g-footer-brand">${logo()}<p>Short tasks, practice games and digital skills for Uganda, Kenya and Tanzania.</p></div><nav aria-label="Product"><h2>Product</h2><a href="#/how-it-works">How it works</a><a href="#/explore">Activities</a><a href="#/pay">How to pay</a><a href="#/pricing">Access and availability</a></nav><nav aria-label="Company"><h2>Company</h2><a href="#/trust">Why trust us</a><a href="#/partners">For partners</a><a href="#/support">Help center</a></nav><nav aria-label="Legal"><h2>Legal</h2><a href="#/terms">Terms of use</a><a href="#/privacy">Privacy notice</a><a href="#/risk">Rewards disclosure</a></nav></div><div class="g-wrap g-footer-base"><p>© ${new Date().getFullYear()} Glorysake. Preview release. Earnings are never guaranteed.</p><p>Fonts: <a href="https://www.onlinewebfonts.com" rel="noopener">Web Fonts</a>, CC BY 4.0${staticMode?'':'. <a href="#/admin">Operations</a>'}</p></div></footer>`;}
function taskCard(t){return `<article class="task-card"><div class="task-top"><span class="activity-icon ${t.color}">${icon(t.icon)}</span><span class="chip">${t.category}</span></div><div class="task-copy"><h3>${t.name}</h3><p>${t.description}</p></div><div class="task-bottom"><span>${icon('clock')} ${t.time}</span><button class="text-btn" data-task="${t.id}">Explore ${icon('arrow')}</button></div><div class="reward-line"><span>Sample reward</span><strong>${money(t.reward)}</strong></div></article>`;}
function menuScreen(id){const t=tasks.find(x=>x.id===id);if(!t)return `<p class="g-dialog-title">Glorysake</p><p>What would you like to try?</p><ol class="g-menu-list">${tasks.map((x,i)=>`<li><button type="button" data-menu="${x.id}"><b>${i+1}</b>${x.short}<span>${x.time}</span></button></li>`).join('')}</ol>`;return `<p class="g-dialog-title">${t.short}</p><p>${t.description}</p><dl><dt>Time</dt><dd>${t.time}</dd><dt>Sample reward</dt><dd class="g-reward">${money(t.reward)}</dd><dt>To complete</dt><dd>${t.criteria.split('. ')[0]}.</dd></dl><ol class="g-menu-list"><li><button type="button" data-menu="go"><b>1</b>Open it in the demo</button></li><li><button type="button" data-menu="root"><b>0</b>Back to the menu</button></li></ol>`;}
function phone(){return `<div class="g-phone" role="group" aria-label="Preview of the Glorysake activity menu"><div class="g-phone-bar" aria-hidden="true"><span>9:41</span><span class="g-phone-cam"></span><span>4G</span></div><div class="g-phone-screen"><div class="g-dialog"><div class="g-dialog-body" id="menu-screen" aria-live="polite">${menuScreen('root')}</div><form class="g-dialog-reply" id="menu-form"><label for="menu-input" class="g-sr">Reply with a number</label><input id="menu-input" inputmode="numeric" autocomplete="off" maxlength="2" placeholder="Reply with a number"><div class="g-dialog-btns"><button type="button" data-menu="root">Cancel</button><button type="submit">Send</button></div></form></div></div></div>`;}
function bindMenu(){const screen=$('#menu-screen'),form=$('#menu-form'),input=$('#menu-input');if(!screen)return;let state='root';const show=v=>{if(v==='go'){go('demo');return;}state=tasks.some(t=>t.id===v)?v:'root';screen.innerHTML=menuScreen(state);};const err=m=>{screen.querySelector('.g-err')?.remove();screen.insertAdjacentHTML('beforeend',`<p class="g-err">${m}</p>`);};$('.g-phone').addEventListener('click',e=>{const b=e.target.closest('[data-menu]');if(!b)return;input.value='';show(b.dataset.menu);});form.addEventListener('submit',e=>{e.preventDefault();e.stopPropagation();const n=input.value.trim();input.value='';if(state==='root'){const t=tasks[Number(n)-1];if(t)show(t.id);else err(`Reply with a number from 1 to ${tasks.length}.`);}else if(n==='1')show('go');else if(n==='0')show('root');else err('Reply 1 to open it, or 0 to go back.');});}
function home(){
const steps=[['Create a free account','Choose your country so amounts show in your own currency.'],['Activate with mobile money','The fee and the merchant code are on the pay page before you send anything.'],['Pick a task and follow its rules','Each task says what counts as done and how many times a day you can do it.'],['Follow the review in your wallet','Pending and approved amounts are kept apart, so you always know where you stand.']];
const rows=tasks.map(t=>`<li class="g-row"><div class="g-row-main"><h3>${t.short}</h3><p>${t.description}</p></div><span class="g-row-meta"><span>${t.category}</span><span>${t.time}</span></span><span class="g-row-reward"><strong>${money(t.reward)}</strong><small>sample reward</small></span><button class="g-btn g-btn-quiet" data-task="${t.id}" aria-label="Details for ${t.short}">Details</button></li>`).join('');
return `${nav()}<main id="main">
<section class="g-hero"><div class="g-wrap g-hero-grid"><div class="g-hero-copy"><h1>Spare minutes, put to good use.</h1><p class="g-lead">Short quizzes, surveys and skill lessons you can finish on a taxi ride. Each one shows the time it takes and its sample reward before you start.</p><div class="g-actions"><a class="g-btn g-btn-primary" href="#/demo">Try the demo</a><a class="g-btn g-btn-secondary" href="#/pay">How to pay</a></div><p class="g-note">Free to explore in Uganda, Kenya and Tanzania. Pay with MTN MoMo or Airtel Money.</p></div><div class="g-hero-stage">${phone()}<p class="g-phone-caption">Tap an option or reply with its number to look around.</p></div></div></section>
<section class="g-section" aria-labelledby="act-h"><div class="g-wrap"><div class="g-head"><h2 id="act-h">What you can do</h2><a class="g-link" href="#/explore">See all activities</a></div><ul class="g-rows">${rows}</ul><p class="g-fine">Rewards shown are samples. In this preview they are virtual and have no cash value.</p></div></section>
<section class="g-section g-steps" aria-labelledby="steps-h"><div class="g-wrap"><h2 id="steps-h">How it works</h2><ol class="g-steplist">${steps.map(([h,p],i)=>`<li><span class="g-step-n" aria-hidden="true">${i+1}</span><h3>${h}</h3><p>${p}</p></li>`).join('')}</ol></div></section>
<section class="g-split" aria-labelledby="friends-h"><div class="g-split-img"><picture><source media="(max-width:560px)" srcset="./assets/img/people-4-mobile.webp" width="1080" height="1920"><img src="./assets/img/people-4-desktop.webp" width="1920" height="1080" alt="Three friends talking over coffee at a cafe table" loading="lazy" decoding="async"></picture><span class="g-tag">Illustrative image</span></div><div class="g-split-copy"><h2 id="friends-h">Better with friends.</h2><p>Share your invite link and learn alongside people you already know. Inviting friends does not earn cash in this release. It is simply more fun together.</p><a class="g-btn g-btn-secondary" href="#/how-it-works">Read how it works</a></div></section>
<section class="g-section" aria-labelledby="pay-h"><div class="g-wrap"><div class="g-head"><h2 id="pay-h">Pay the way you already do.</h2><a class="g-link" href="#/pay">Step-by-step payment guide</a></div><div class="g-codes"><div class="g-code mtn"><img src="./assets/mtn-logo.svg" alt="MTN" width="68" height="34"><p>MTN Mobile Money</p><strong>*165*3#</strong></div><div class="g-code airtel"><img src="./assets/airtel-logo.svg" alt="Airtel" width="132" height="34"><p>Airtel Money</p><strong>*185#</strong></div></div><p class="g-fine">Only pay to the merchant code shown on our pay page. Never send money to a personal number.</p></div></section>
<section class="g-section" aria-labelledby="trust-h"><div class="g-wrap g-trust-grid"><div><h2 id="trust-h">Straight answers.</h2><ul class="g-facts"><li><h3>No promised income</h3><p>Earnings depend on available tasks and approval. We never guarantee money.</p></li><li><h3>Rules before you start</h3><p>Requirements, time and daily limits are shown up front.</p></li><li><h3>A wallet that keeps things apart</h3><p>Available, pending and approved amounts are always shown separately.</p></li></ul><a class="g-link" href="#/trust">How we keep it fair</a></div><div class="faqs">${faqMarkup(faqs.slice(0,5))}</div></div></section>
<section class="g-cta"><div class="g-wrap g-cta-inner"><div><h2>See it before you sign up.</h2><p>The demo runs in your browser with practice tasks and a virtual wallet. There is nothing to pay.</p></div><a class="g-btn g-btn-onviolet" href="#/demo">Try the demo</a></div></section>
</main>${footer()}`;}
const faqMarkup=(list)=>list.map(([q,a])=>`<details><summary>${q}<span>+</span></summary><p>${a}</p></details>`).join('');
function publicPage(kind){const content={
'how-it-works':['A little effort. A clear path.','HOW GLORYSAKE WORKS','Explore first. Choose an activity. Read the rules. Complete the work. Follow the review. Every step should make sense.',`<div class="steps-grid">${[['01','Find your fit','Browse skills, surveys, partner activities and practice games.'],['02','Know the details','Each task explains its requirements, time estimate, sample reward and daily limit.'],['03','Follow the outcome','Completed tasks appear in your history. Submitted work stays pending until reviewed.']].map(([n,h,p])=>`<article><span class="step-no">${n}</span><h3>${h}</h3><p>${p}</p></article>`).join('')}</div><div class="notice">The preview uses practice tasks and virtual rewards. Live opportunities will be listed separately when funded and available.</div>`],
trust:['Clarity is the whole point.','TRUST & TRANSPARENCY','You deserve to understand the opportunity, the requirements and the outcome.',`<div class="cards-three">${[['Clear activity rules','Every task shows the completion criteria, daily cap and review requirements.'],['Visible reward status','Your wallet separates approved rewards from pending reviews. Demo balances never represent real money.'],['Responsible growth','No cash reward for recruitment in this release. No investments, loans or wagering.']].map(([h,p])=>`<article class="panel">${icon('shield')}<h3>${h}</h3><p>${p}</p></article>`).join('')}</div><h2 class="space-top">Built to earn your trust over time.</h2><p>No invented payout counters, fabricated testimonials or income promises. Payment services are unavailable until provider onboarding and market approvals are complete.</p>`],
pricing:['Free to join. Clear from day one.','ACCESS & AVAILABILITY','Any activation amount is published on the How to pay page. Payments are made to the official mobile money merchant code and confirmed manually. Nothing is guaranteed.',`<div class="pricing-card"><span class="chip">PREVIEW ACCESS</span><h2>Free<span class="muted"> / to explore</span></h2><p>Explore every preview activity and the member dashboard.</p><ul class="check-list"><li>Practice quizzes and skill games</li><li>Sample task and wallet experience</li><li>Free account registration on server hosting</li><li>No deposit or payment details required</li></ul>${button('Explore the demo','demo')}</div><h2 class="space-top">Country settings</h2><div class="cards-three">${Object.values(countries).map(c=>`<article class="panel"><h3>${c.flag} ${c.name}</h3><p>${c.currency} display preference</p><span class="chip">Live payouts not enabled</span></article>`).join('')}</div>`],
partners:['Meaningful participation. Measurable value.','FOR PARTNERS','Turn your research questions and digital projects into clear, useful activities.',`<div class="steps-grid"><article><span class="step-no">01</span><h3>Define the work.</h3><p>Set eligibility, completion rules, review criteria and a capped budget.</p></article><article><span class="step-no">02</span><h3>Fund the activity.</h3><p>Rewards require confirmed sponsor funding before activities can become available.</p></article><article><span class="step-no">03</span><h3>Review the results.</h3><p>Track submissions, approve valid work and retain a record of every decision.</p></article></div><h2 class="space-top">Plan a campaign.</h2>${supportForm('Partnership enquiry')}`],
terms:['Terms of use','THE DETAILS','Preview terms · Version 10 November 2026',`<div class="legal-copy"><h2>Using the preview</h2><p>Glorysake is currently a product preview. Practice activities and virtual wallet balances have no cash value. Access is intended for people aged 18 or older.</p><h2>Accounts and activity</h2><p>Provide accurate information, protect your login and maintain one account. Do not automate submissions, impersonate others or interfere with the service. Work may be reviewed or rejected against the published task criteria.</p><h2>Rewards and payments</h2><p>No earnings are guaranteed. Task availability and rewards depend on funding, eligibility and approval. Payments are made outside this site through MTN or Airtel mobile money and confirmed manually. Live withdrawals are not yet available. Future paid activities will need their own approved terms before launch.</p><h2>Support and changes</h2><p>Use the help center for account or activity questions. Final operator identity, country-specific terms and dispute policies must be published before any live money launch. These preview terms do not replace those policies.</p></div>`],
privacy:['Your data deserves care.','PRIVACY NOTICE','Preview notice · Version 10 November 2026',`<div class="legal-copy"><h2>What this release stores</h2><p>Server accounts store your name, email, country, password hash, session records and support requests. Passwords are hashed. The browser demo stores sample progress and preferences on your device.</p><h2>Why it is stored</h2><p>Account data supports sign-in, profile settings and support. Task submissions support review. Session cookies are HttpOnly and use SameSite protection. This release does not use advertising trackers.</p><h2>Your choices</h2><p>You can reset device demo progress in settings. Server account export and deletion are available in account settings. Signing out removes the session. Do not send identity documents or payment credentials through the support form.</p><h2>Before public financial launch</h2><p>The operator must publish its legal identity, privacy contact, retention schedule, hosting location and market-specific rights process. No live identity-document collection or payment processing is enabled in this release.</p></div>`],
risk:['Know what you’re joining.','REWARDS DISCLOSURE','Clear expectations make a better experience.',`<div class="legal-copy"><h2>No guaranteed earnings</h2><p>Glorysake does not promise income. Task eligibility, available budgets and quality reviews determine whether any live reward can be earned.</p><h2>Demo balances are virtual</h2><p>All rewards in the interactive demo are examples. They cannot be deposited, transferred, sold or withdrawn. Real accounts begin with a zero balance.</p><h2>No financial products</h2><p>Deposits, investments, loans, interest-bearing plans and cash-stake games are disabled. Referral cash commissions are also disabled.</p><h2>Live payout readiness</h2><p>Live payments require an authorized provider, identity checks, reconciliation, confirmed task funding and completed market approvals. The interface alone does not provide these capabilities.</p></div>`]
}[kind];return `${nav()}<main id="main" class="g-page"><div class="g-wrap"><header class="g-page-head"><h1>${content[0]}</h1><p class="g-lead">${content[2]}</p></header>${content[3]}</div></main>${footer()}`;}
function supportForm(subject=''){if(staticMode)return '<div class="notice">The interactive preview is open. Support enquiries will be available when account services launch.</div>';return `<form id="support-form" class="form-grid"><label>Your name<input name="name" required maxlength="100" autocomplete="name"></label><label>Email address<input name="email" type="email" required autocomplete="email"></label><label>Topic<select name="subject"><option>${subject||'General question'}</option><option>Account access</option><option>Task review</option><option>Partnership enquiry</option><option>Privacy request</option></select></label><label class="full">How can we help?<textarea name="message" required minlength="10" maxlength="3000" rows="4"></textarea></label><div class="full"><button class="btn primary" type="submit">Send enquiry ${icon('arrow')}</button><p class="fineprint">Please leave out passwords, OTPs and payment credentials.</p></div><p class="form-error full" role="alert"></p></form>`;}
function support(){return `${nav()}<main id="main" class="g-page"><div class="g-wrap"><header class="g-page-head"><h1>Help center</h1><p class="g-lead">Answers to the questions people ask most. If yours is not here, send us a message.</p></header><div class="faqs">${faqMarkup(faqs)}</div><div class="support-grid"><div><h2>Ask us something</h2><p class="muted">Your message goes to the support queue. Keep the reference number we send back.</p></div>${supportForm()}</div></div></main>${footer()}`;}
function explore(app=false){const tools=`<div class="explore-toolbar"><div class="tabs" role="group" aria-label="Activity category">${['All','Skills','Surveys','Games','Partners'].map(x=>`<button class="${filter===x?'active':''}" data-filter="${x}" aria-pressed="${filter===x}">${x}</button>`).join('')}</div><label class="search-box">${icon('search')}<input id="task-search" aria-label="Search activities" placeholder="Search activities" value="${esc(search)}"></label></div><div class="cards-three" id="task-list">${filteredTasks()}</div>`;if(app)return `<main id="main"><span class="eyebrow">FIND YOUR THING</span><h1>What will you try today?</h1><p class="page-lead">Pick something that sparks your curiosity. Every activity starts with clear rules.</p>${tools}<p class="fineprint">Practice activities · Virtual sample rewards · Not withdrawable</p></main>`;return `${nav()}<main id="main" class="g-page"><div class="g-wrap"><header class="g-page-head"><h1>Activities</h1><p class="g-lead">Each activity lists its rules, the time it takes and a sample reward before you start.</p></header>${tools}<p class="g-fine">These are practice activities. Rewards are virtual samples and cannot be withdrawn.</p></div></main>${footer()}`;}
function filteredTasks(){const result=tasks.filter(t=>(filter==='All'||t.category===filter)&&[t.name,t.short,t.description].join(' ').toLowerCase().includes(search.toLowerCase()));return result.length?result.map(taskCard).join(''):'<div class="empty-state">No matches yet. Try a different search.</div>';}
function authPage(register){return `${nav()}<main id="main" class="auth-layout"><div class="auth-story"><span class="eyebrow">YOUR NEXT CHAPTER</span><h1>Good things<br>start with<br><em>showing up.</em></h1><p>One account. A little curiosity.<br>A world of small possibilities.</p><img src="./assets/logo-white.png" alt="" class="auth-mark"></div><div class="auth-form-wrap"><span class="eyebrow">${register?'MAKE YOURSELF AT HOME':'GOOD TO HAVE YOU BACK'}</span><h2>${register?'Your story starts here.':'Welcome back.'}</h2><p class="muted">${register?'Create your free Glorysake account.':'Pick up where you left off.'}</p><form id="auth-form" data-register="${register}">${register?'<label>Your name<input name="name" autocomplete="name" required maxlength="80" placeholder="How should we call you?"></label>':''}<label>Email address<input name="email" type="email" required autocomplete="email" placeholder="you@example.com"></label><label>Password<input name="password" type="password" minlength="12" maxlength="128" autocomplete="${register?'new-password':'current-password'}" required placeholder="${register?'At least 12 characters':'Enter your password'}"></label>${register?`<label>Your country<select name="country">${Object.entries(countries).map(([k,c])=>`<option value="${k}">${c.flag} ${c.name}</option>`).join('')}</select></label><label class="checkbox"><input type="checkbox" name="consent" required><span>I am 18 or older and agree to the <a href="#/terms">Terms</a> and <a href="#/privacy">Privacy notice</a>.</span></label>`:''}<p class="form-error" role="alert"></p><button class="btn primary full-width" type="submit">${register?'Create free account':'Log in'} ${icon('arrow')}</button></form><p class="auth-switch">${register?'Already feel at home? <a href="#/login">Log in</a>':'New here? <a href="#/register">Create an account</a>'}</p><div class="divider"><span>or get a feel for it first</span></div>${button('Explore the interactive demo','demo','outline full-width')}<p class="fineprint">Preview release. No activation fees or live cash rewards.</p></div></main>${footer()}`;}
function ensureDemo(){if(!demo){demo={name:'Alex',country:'UG',completed:[],transactions:[],pending:[],balance:0};save();}}
const appNav=[['dashboard','grid','Overview'],['tasks','spark','Explore & earn'],['games','bolt','Play & learn'],['wallet','wallet','My wallet'],['team','users','My circle'],['learning','book','Learning hub'],['messages','message','Help & messages'],['settings','settings','Settings']];
function shell(route,content){const who=demo||user||{name:'Member'};return `<div class="app-layout"><aside class="sidebar">${logo(true)}<div class="sidebar-label">YOUR EVERYDAY, UPGRADED</div><nav aria-label="Member navigation">${appNav.map(([p,i,n])=>`<a href="#/${p}" class="${route===p?'selected':''}">${icon(i)}<span>${n}</span>${p==='tasks'?'<small>6</small>':''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="preview-card">${icon('spark')}<strong>A space to explore.</strong><p>${demo?'You’re in the demo. Your rewards are virtual.':'Your account is ready. Live tasks are not open yet.'}</p><a href="#/">Visit the website ${icon('arrow')}</a></div><button class="text-btn" data-action="logout">${icon('logout')} ${demo?'Leave demo':'Log out'}</button></div></aside><div class="app-body"><header class="app-header"><a class="mobile-brand" href="#/dashboard">${logo(true).replace(/<a[^>]*>|<\/a>/g,'')}</a><span class="breadcrumb">Your space <span>/</span> ${appNav.find(x=>x[0]===route)?.[2]||'Operations'}</span><div class="app-header-right"><span class="demo-tag">${demo?'INTERACTIVE DEMO':'PREVIEW ACCOUNT'}</span><a href="#/settings" class="profile-badge" aria-label="Account settings">${esc(who.name.charAt(0).toUpperCase())}</a></div></header><div class="preview-banner">${icon('spark')} ${demo?'A little look into what’s next. Activities and rewards here are for practice — no real money.':'Welcome to the preview. Live paid tasks and withdrawals are not open yet.'}${demo?'<button data-action="reset-demo">Reset demo</button>':''}</div><div class="app-content">${content}</div><nav class="bottom-nav" aria-label="Mobile member navigation">${appNav.filter(x=>['dashboard','tasks','wallet','settings'].includes(x[0])).map(([p,i,n])=>`<a href="#/${p}" class="${p===route?'selected':''}">${icon(i)}<span>${p==='wallet'?'Wallet':n.split(' ')[0]}</span></a>`).join('')}</nav></div></div>`;}
function overview(){const who=demo||user;return `<main id="main"><div class="dashboard-heading"><div><span class="eyebrow">A FRESH START LOOKS GOOD ON YOU</span><h1>Hey, ${esc(who.name.split(' ')[0])}<span class="wave">${icon('spark')}</span></h1><p class="muted">A little progress is still progress. Let’s make today count.</p></div><span class="date-chip">${new Date().toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short'})}</span></div><div class="dashboard-grid"><section class="wallet-hero"><span class="eyebrow">${demo?'VIRTUAL':'AVAILABLE'} BALANCE</span><h2>${money(demo?.balance||0)}</h2><p>${demo?'Every small win, all in one place.':'Your approved rewards will appear here.'}</p><a href="#/wallet" class="btn light small">View wallet ${icon('arrow')}</a><img src="./assets/logo-white.png" alt=""></section><section class="mini-stat"><span class="activity-icon peach">${icon('clock')}</span><span>Pending review</span><strong>${money((demo?.pending||[]).reduce((a,t)=>a+t.reward,0))}</strong><small>Waiting for a quality check</small></section><section class="mini-stat"><span class="activity-icon sky">${icon('check')}</span><span>Tasks completed</span><strong>${demo?.completed.length||0}<span class="muted"> / 6</span></strong><small>Your curiosity is going places.</small></section></div><div class="dashboard-two"><section><div class="section-heading compact"><div><span class="eyebrow">A LITTLE SOMETHING FOR YOU</span><h2>Your next small win.</h2></div><a class="text-link" href="#/tasks">View all ${icon('arrow')}</a></div><div class="task-rows">${tasks.slice(0,4).map(t=>`<button class="task-row" data-task="${t.id}"><span class="activity-icon ${t.color}">${icon(t.icon)}</span><span class="row-title"><strong>${t.short}</strong><small>${t.category} · ${t.time}</small></span><span class="row-reward">${money(t.reward)}<small>Sample reward</small></span>${icon('chevron')}</button>`).join('')}</div></section><section class="daily-card"><span class="eyebrow">A MINUTE FOR YOUR MIND</span><div class="daily-art">${icon('spark')}</div><h2>Stay curious.<br>Go a little further.</h2><p>Build useful digital habits, one little lesson at a time.</p><a href="#/learning" class="text-link">Visit the learning hub ${icon('arrow')}</a></section></div><section class="getting-started"><h3>A good place to start.</h3><div>${[['Explore your first task','tasks'],['Get to know your wallet','wallet'],['Make this space yours','settings']].map(([n,p],i)=>`<a href="#/${p}"><span>${i+1}</span>${n}${icon('arrow')}</a>`).join('')}</div></section></main>`;}
function wallet(){let list=demo?.transactions||[];return `<main id="main"><span class="eyebrow">EVERY STEP, ACCOUNTED FOR</span><h1>Your wallet. No guesswork.</h1><p class="page-lead">The big picture and the little details, together.</p><div class="wallet-summary"><section class="wallet-hero"><span class="eyebrow">${demo?'VIRTUAL':'AVAILABLE'} BALANCE</span><h2>${money(demo?.balance||0)}</h2><p>${demo?'Demo rewards cannot be withdrawn.':'No approved live rewards yet.'}</p><button class="btn light small" data-action="withdraw">Explore withdrawal ${icon('arrow')}</button></section><div class="panel"><span class="muted">Pending review</span><h2>${money((demo?.pending||[]).reduce((a,t)=>a+t.reward,0))}</h2><p>Separate from your available balance.</p></div><div class="panel"><span class="muted">Total paid out</span><h2>UGX 0</h2><p>No live payments in the preview.</p></div></div><div class="section-heading compact"><h2>The story so far.</h2><button class="btn outline small" data-action="export">${icon('download')} Export statement</button></div><div class="table-wrap"><table><thead><tr><th>Activity</th><th>Reference</th><th>Date</th><th>Amount</th><th>Status</th></tr></thead><tbody>${list.length?list.map(t=>`<tr><td><strong>${esc(t.name)}</strong></td><td>${esc(t.id)}</td><td>${new Date(t.date).toLocaleDateString('en-GB')}</td><td>+${money(t.amount)}</td><td><span class="chip success">Practice credit</span></td></tr>`).join(''):'<tr><td colspan="5" class="empty-state">A fresh page. Complete a practice activity to see your first entry.</td></tr>'}</tbody></table></div><div class="notice">${icon('shield')} Live withdrawals are disabled. When available, fees, limits, destination verification and provider status must be shown before you confirm.</div></main>`;}
function games(){return `<main id="main"><span class="eyebrow">A QUICK CHANGE OF PACE</span><h1>Play a little. Learn a little.</h1><p class="page-lead">Small challenges for a sharper everyday. No stakes. No cash prizes.</p><div class="cards-three">${tasks.filter(t=>t.category==='Games'||t.id==='quiz').map(taskCard).join('')}</div></main>`;}
function team(){return `<main id="main"><span class="eyebrow">GOOD COMPANY, GOOD MOMENTUM</span><h1>Your circle starts with you.</h1><p class="page-lead">An interesting discovery is even better when you share it.</p><div class="dashboard-two"><section class="panel invite-panel"><span class="activity-icon violet">${icon('users')}</span><h2>Bring someone curious.</h2><p>Invite a friend to explore Glorysake. There are no referral cash rewards in this release.</p><label>Your invite link<div class="copy-field"><input readonly value="${esc(location.origin+location.pathname+'#/register?ref=explore')}" aria-label="Your invite link"><button class="icon-btn" data-action="copy">${icon('copy')}</button></div></label></section><section class="panel"><h3>A circle built on real value.</h3><ul class="check-list"><li>Share the opportunity honestly</li><li>No guaranteed income claims</li><li>No activation-fee commissions</li><li>No self-referrals or duplicate accounts</li></ul></section></div></main>`;}
function learning(){return `<main id="main"><span class="eyebrow">CURIOUS LOOKS GOOD ON YOU</span><h1>A little wiser, every day.</h1><p class="page-lead">Practical ideas for a more confident digital life.</p><div class="learning-grid">${[['01','Safer online, in five minutes.','Passwords, phishing and the small habits that protect you.','learn'],['02','Know a good opportunity.','Read task rules, spot unrealistic promises and protect your time.','opportunity'],['03','Your wallet, explained.','Available, pending and paid out. Three labels that matter.','wallet-lesson']].map(([n,h,p,id])=>`<button class="lesson-card" data-lesson="${id}"><span class="step-no">${n}</span>${icon('book')}<h2>${h}</h2><p>${p}</p><span class="text-link">Read the guide ${icon('arrow')}</span></button>`).join('')}</div></main>`;}
function messages(){return `<main id="main"><span class="eyebrow">LET’S KEEP IT CLEAR</span><h1>A little help goes a long way.</h1><p class="page-lead">Find an answer, or leave a question with the support team.</p><div class="faqs wide-faq">${faqMarkup(faqs.slice(0,4))}</div><section class="panel space-top"><h2>Start a conversation.</h2>${supportForm()}</section></main>`;}
function settings(){const who=demo||user;return `<main id="main"><span class="eyebrow">MAKE YOURSELF AT HOME</span><h1>Your space, your details.</h1><p class="page-lead">A few small preferences make things feel more like you.</p><section class="panel settings-panel"><form id="settings-form"><label>Name<input name="name" value="${esc(who.name)}" required maxlength="80"></label><label>Country<select name="country">${Object.entries(countries).map(([k,c])=>`<option value="${k}" ${k===who.country?'selected':''}>${c.flag} ${c.name}</option>`).join('')}</select></label><p class="fineprint">Country is a profile preference. Practice rewards are always shown in UGX; it does not enable live payments.</p><button class="btn primary" type="submit">Save changes ${icon('check')}</button><p class="form-error" role="alert"></p></form></section><section class="panel settings-panel space-top"><h3>Your data, your choice.</h3><p>${demo?'Reset your virtual progress on this device whenever you like.':'Export your account information or permanently delete your account.'}</p><div class="button-row"><button class="btn outline" data-action="${demo?'reset-demo':'account-export'}">${demo?'Reset demo progress':'Export account data'}</button>${demo?'':'<button class="btn danger" data-action="delete-account">Delete account</button>'}</div></section></main>`;}
async function admin(){if(demo||!user||user.role!=='admin')return `${nav()}<main id="main" class="public-page wrap"><span class="eyebrow">GLORYSAKE OPERATIONS</span><h1>A thoughtful platform.<br>A responsible operation.</h1><p class="page-lead">Operator access requires a server account with the admin role.</p>${button('Operator sign in','login')}<div class="notice">No public account can grant itself operator access. Configure the administrator using the server bootstrap command.</div></main>${footer()}`;const data=await api('admin/overview');return shell('admin',`<main id="main"><span class="eyebrow">OPERATIONS</span><h1>A clear view of the work.</h1><div class="cards-three">${[['Registered members',data.users],['Open support requests',data.tickets.length],['Campaign drafts',data.campaigns.length]].map(([n,v])=>`<section class="panel"><span>${n}</span><h2>${v}</h2></section>`).join('')}</div><section class="panel space-top"><h2>Campaign studio</h2><p>Plan funded work. Campaigns are saved as drafts; paid distribution stays disabled until payment and review infrastructure is approved.</p><form id="campaign-form" class="form-grid"><label>Campaign title<input name="title" required maxlength="120"></label><label>Reward budget (UGX)<input name="budget" type="number" min="0" step="1" required></label><label class="full">Completion criteria<textarea name="criteria" minlength="10" required></textarea></label><button class="btn primary">Save draft ${icon('plus')}</button><p class="form-error" role="alert"></p></form>${data.campaigns.map(c=>`<div class="admin-row"><strong>${esc(c.title)}</strong><span>${money(c.budget)}</span><span class="chip">Draft</span></div>`).join('')}</section><section class="panel space-top"><h2>Support inbox</h2>${data.tickets.length?data.tickets.map(t=>`<article class="support-ticket"><span class="chip">${esc(t.status)}</span><h3>${esc(t.subject)}</h3><small>${esc(t.name)} · ${esc(t.email)} · ${esc(t.id)}</small><p>${esc(t.message)}</p>${t.status==='open'?`<button class="btn outline small" data-resolve="${esc(t.id)}">Mark resolved</button>`:''}</article>`).join(''):'<p>No requests yet.</p>'}</section><section class="panel space-top"><h2>Audit trail</h2>${data.audits.map(a=>`<div class="admin-row"><span>${esc(a.action)}</span><small>${esc(a.created_at)}</small></div>`).join('')}</section></main>`);}
function openModal(html){const el=$('#modal');el.innerHTML=`<button class="modal-close icon-btn" aria-label="Close dialog" data-action="close">${icon('close')}</button>${html}`;el.showModal();}
function taskDetail(id){const t=tasks.find(t=>t.id===id);if(!t)return;openModal(`<span class="activity-icon ${t.color}">${icon(t.icon)}</span><span class="eyebrow space-top">${t.category} · PRACTICE ACTIVITY</span><h2 id="modal-title">${t.short}</h2><p>${t.description}</p><div class="task-detail-stats"><div><small>Sample reward</small><strong>${money(t.reward)}</strong></div><div><small>Time estimate</small><strong>${t.time}</strong></div></div><h3>What’s involved</h3><p>${t.criteria}</p><div class="notice">Demo only. Virtual rewards have no cash value. One practice credit per activity on this device.</div><button class="btn primary full-width" data-start="${t.id}">${demo?.completed.includes(t.id)?'Practice again':'Give it a try'} ${icon('arrow')}</button>`);}
function startTask(id){if(!demo){$('#modal').close();ensureDemo();go('tasks');toast('You’re in the practice demo. Nothing here involves real money.');}playing=tasks.find(t=>t.id===id);step=0;answers=[];if(['quiz','math'].includes(playing.type))renderQuestion();else if(playing.type==='color')colorRound();else if(playing.type==='learn')lesson('learn');else openModal(`<span class="eyebrow">PRACTICE ${playing.category.toUpperCase()}</span><h2 id="modal-title">${playing.short}</h2><form id="practice-form">${playing.type==='survey'?'<label>How do you usually discover new products?<select name="discovery" required><option value="">Choose one</option><option>Friends and family</option><option>Social media</option><option>Shops and markets</option><option>Online search</option></select></label><label>What matters most when choosing a product?<select name="priority" required><option value="">Choose one</option><option>Quality</option><option>Price</option><option>Recommendations</option><option>Convenience</option></select></label><label>Tell us why (at least 20 characters)<textarea name="proof" required minlength="20" maxlength="1000"></textarea></label>':'<img class="review-image" src="./assets/community.webp" alt="Sample cafe photograph for image review"><label>Describe two quality observations (at least 20 characters)<textarea name="proof" required minlength="20" maxlength="1000"></textarea></label>'}<p class="fineprint">Practice submission only. No personal or sensitive information.</p><button class="btn primary full-width">Submit for practice review ${icon('arrow')}</button></form>`);}
function renderQuestion(){const set=playing.type==='math'?math:quiz,q=set[step];openModal(`<span class="eyebrow">${playing.short.toUpperCase()} · ${step+1} OF ${set.length}</span><div class="progress-track"><span style="width:${(step+1)/set.length*100}%"></span></div><h2 id="modal-title">${q.q}</h2><div class="answer-options">${q.a.map((a,i)=>`<button data-answer="${i}"><span>${String.fromCharCode(65+i)}</span>${a}${icon('chevron')}</button>`).join('')}</div><p class="fineprint">Practice activity · No cash reward</p>`);}
function finishQuiz(){const set=playing.type==='math'?math:quiz,score=answers.filter((a,i)=>a===set[i].correct).length;let credited=false;if(score>=4&&!demo.completed.includes(playing.id)){credit(playing);credited=true;}openModal(`<span class="result-art">${score>=4?'✳':'↗'}</span><span class="eyebrow">A LITTLE WISER ALREADY</span><h2 id="modal-title">${score>=4?'That’s a small win.':'Keep that curiosity going.'}</h2><p>You answered ${score} of ${set.length} correctly. ${credited?money(playing.reward)+' added to your virtual demo wallet.':score>=4?'You’ve already earned this practice credit.':'Score 4 or more to unlock the virtual practice credit.'}</p><p class="fineprint">Virtual credits are not real money and cannot be withdrawn.</p><div class="answer-review">${set.map((q,i)=>`<p><strong>${answers[i]===q.correct?'✓':'○'} ${q.q}</strong><br><span>${q.a[q.correct]}</span></p>`).join('')}</div><button class="btn primary full-width" data-action="close">Keep exploring ${icon('arrow')}</button>`);render(false);}
function credit(t){demo.completed.push(t.id);demo.balance+=t.reward;demo.transactions.unshift({id:'DEMO-'+crypto.randomUUID().slice(0,8).toUpperCase(),name:t.short,amount:t.reward,date:new Date().toISOString()});save();dispatchEvent(new Event('fx:confetti'));}
let targetColor=0;function colorRound(){const palette=['#7c5ce9','#a3d8c2','#f0bc91','#99dbeb'];targetColor=(step*3+1)%4;openModal(`<span class="eyebrow">COLOR MATCH · ROUND ${step+1} OF 5</span><h2 id="modal-title">Find the matching shade.</h2><div class="color-target" style="background:${palette[targetColor]}"></div><div class="color-options">${palette.map((c,i)=>`<button data-color="${i}" style="background:${c}" aria-label="${['Violet','Mint','Peach','Sky blue'][i]}"></button>`).join('')}</div><p class="fineprint">Practice recognition game. No cash prize.</p>`);}
function lesson(id){let h,p;if(id==='learn'){h='A safer internet starts with small habits.';p='<h3>1. Make passwords unique.</h3><p>Use a long passphrase for each account. A password manager helps you keep track.</p><h3>2. Keep your OTP to yourself.</h3><p>Legitimate support should never need your sign-in code or password.</p><h3>3. Pause before you tap.</h3><p>Check the sender, the URL and the request. A promise of guaranteed income or urgent payment deserves a second look.</p>';}else if(id==='opportunity'){h='Know what you’re giving your time to.';p='<p>Read the task requirements, reward status, review process and daily limit. Avoid any offer that promises guaranteed income or asks you to recruit others to recover a fee. Ask questions before you commit.</p>';}else{h='Three labels. One clearer wallet.';p='<h3>Available</h3><p>Approved rewards eligible for the next supported action.</p><h3>Pending</h3><p>Work submitted, with a review still outstanding.</p><h3>Paid out</h3><p>A withdrawal confirmed by the payment provider. A submitted request alone is not a successful payout.</p>';}openModal(`<span class="eyebrow">THE LEARNING HUB</span><h2 id="modal-title">${h}</h2>${p}${id==='learn'?'<h3>Quick check: should you share an OTP with someone claiming to be support?</h3><div class="answer-options"><button data-learn-answer="wrong">Yes, if they ask politely</button><button data-learn-answer="correct">No. Keep sign-in codes private.</button></div>':'<button class="btn primary" data-action="close">Good to know '+icon('check')+'</button>'}`);}
async function render(scroll=true){const route=(location.hash.slice(2).split('?')[0]||'');if(scroll)window.scrollTo(0,0);let html;if(route==='demo'){ensureDemo();go('dashboard');return;}if(['dashboard','tasks','games','wallet','team','learning','messages','settings'].includes(route)){if(!demo&&!user){go('login');return;}const pages={dashboard:overview,tasks:()=>explore(true),games,wallet,team,learning,messages,settings};html=shell(route,pages[route]());}else if(route==='admin')html=await admin();else if(route==='register'||route==='login'){if(staticMode){go('demo');return;}html=authPage(route==='register');}else if(route==='explore')html=explore();else if(route==='support')html=support();else if(route==='pay')html=payPage({nav,footer,icon,staticMode});else if(['how-it-works','trust','pricing','partners','terms','privacy','risk'].includes(route))html=publicPage(route);else if(!route)html=home();else html=`${nav()}<main id="main" class="public-page wrap"><h1>This path is still unwritten.</h1><p>Let’s get you somewhere useful.</p>${button('Back to Glorysake','','primary')}</main>${footer()}`;$('#app').innerHTML=html;document.body.classList.toggle('site',!['dashboard','tasks','games','wallet','team','learning','messages','settings','admin'].includes(route));enhance();{const names={dashboard:'Your space','how-it-works':'How it works',explore:'Activities',pay:'How to pay',trust:'Why trust us',support:'Help center',pricing:'Access and availability',partners:'For partners',terms:'Terms of use',privacy:'Privacy notice',risk:'Rewards disclosure',login:'Log in',register:'Join free'};const n=names[route]||(route?route.charAt(0).toUpperCase()+route.slice(1).replaceAll('-',' '):'');document.title=n?n+' | Glorysake':'Glorysake | Spare minutes, put to good use';}}
function enhance(){
bindMenu();
const reduce=matchMedia('(prefers-reduced-motion:reduce)').matches;const els=document.querySelectorAll('[data-reveal]');
if(reduce||!('IntersectionObserver' in window)){els.forEach(e=>e.classList.add('in'));document.querySelectorAll('[data-count]').forEach(c=>c.textContent=c.dataset.count);}
else{const io=new IntersectionObserver(es=>es.forEach(e=>{if(!e.isIntersecting)return;e.target.classList.add('in');const c=e.target.querySelector('[data-count]');if(c)countUp(c);io.unobserve(e.target);}),{threshold:.15});els.forEach(e=>io.observe(e));}
if(matchMedia('(hover:hover) and (pointer:fine)').matches&&!reduce)document.querySelectorAll('.tilt').forEach(c=>{c.addEventListener('pointermove',ev=>{const r=c.getBoundingClientRect(),x=(ev.clientX-r.left)/r.width-.5,y=(ev.clientY-r.top)/r.height-.5;c.style.transform=`perspective(700px) rotateX(${-y*6}deg) rotateY(${x*8}deg) translateY(-4px)`;});c.addEventListener('pointerleave',()=>{c.style.transform='';});});
}
function countUp(el){const n=+el.dataset.count,t0=performance.now();const f=t=>{const p=Math.min(1,(t-t0)/1100);el.textContent=Math.round(n*(1-Math.pow(1-p,3)));if(p<1)requestAnimationFrame(f);};requestAnimationFrame(f);}
bindPay({api,toast,staticMode});
window.addEventListener('scroll',()=>document.querySelector('.public-header')?.classList.toggle('scrolled',scrollY>20),{passive:true});
window.addEventListener('hashchange',()=>{render().catch(e=>toast(e.message));});
document.addEventListener('input',e=>{if(e.target.id==='task-search'){search=e.target.value;$('#task-list').innerHTML=filteredTasks();}});
document.addEventListener('click',async e=>{const el=e.target.closest('button,[data-task],[data-lesson]');if(!el)return;try{if(el.dataset.task)taskDetail(el.dataset.task);if(el.dataset.filter){filter=el.dataset.filter;render(false);}if(el.dataset.start)startTask(el.dataset.start);if(el.dataset.lesson)lesson(el.dataset.lesson);if(el.dataset.learnAnswer){if(el.dataset.learnAnswer==='correct'){if(!demo){ensureDemo();go('learning');}if(!demo.completed.includes('learn'))credit(tasks.find(t=>t.id==='learn'));openModal('<span class="result-art">'+icon('spark')+'</span><h2 id="modal-title">Good habits. Good progress.</h2><p>You completed the digital skills lesson. Your virtual practice progress is saved.</p><button class="btn primary" data-action="close">Keep exploring</button>');render(false);}else toast('Keep your codes private. Try the other answer.');}if(el.dataset.answer!==undefined){answers.push(Number(el.dataset.answer));step++;step>=5?finishQuiz():renderQuestion();}if(el.dataset.color!==undefined){if(Number(el.dataset.color)!==targetColor){toast('Take another look. Match the target shade.');return;}step++;if(step>=5){if(!demo.completed.includes('color'))credit(tasks.find(t=>t.id==='color'));openModal('<span class="result-art">✳</span><h2 id="modal-title">A moment of focus. Well spent.</h2><p>You matched all five shades. Your virtual practice progress is saved.</p><button class="btn primary" data-action="close">Keep exploring</button>');render(false);}else colorRound();}if(el.dataset.resolve){await api('admin/tickets/'+el.dataset.resolve,{status:'resolved'},'PATCH');await render(false);toast('Request resolved.');}switch(el.dataset.action){case'menu':{const n=$('.mobile-nav');n.hidden=!n.hidden;el.setAttribute('aria-expanded',String(!n.hidden));break;}case'close':$('#modal').close();break;case'logout':if(demo){demo=null;localStorage.removeItem('gs-demo');}else{await api('logout',{});user=null;}go('');break;case'reset-demo':demo=null;localStorage.removeItem('gs-demo');ensureDemo();render(false);toast('A fresh start. Demo progress reset.');break;case'withdraw':openModal('<span class="eyebrow">CLARITY BEFORE CASHOUT</span><h2 id="modal-title">Not quite time for that step.</h2><p>Live withdrawals are not enabled. Demo rewards are virtual and cannot be paid out.</p><div class="withdraw-steps"><span>01 · Confirm eligibility</span><span>02 · Review minimum, fee and net amount</span><span>03 · Verify the payout destination</span><span>04 · Track the provider receipt</span></div><p class="fineprint">Payment provider onboarding and country availability must be complete before launch.</p><button class="btn primary" data-action="close">Got it</button>');break;case'copy':await navigator.clipboard.writeText($('.copy-field input').value);toast('Invite link copied.');break;case'export':download('glorysake-demo-statement.csv','Reference,Activity,Amount UGX,Status,Date\n'+(demo?.transactions||[]).map(t=>[t.id,t.name,t.amount,'Virtual practice credit',t.date].map(csv).join(',')).join('\n'),'text/csv');toast('Statement exported.');break;case'account-export':download('glorysake-account.json',JSON.stringify(await api('account/export'),null,2),'application/json');break;case'delete-account':openModal('<h2 id="modal-title">Delete your account?</h2><p>This permanently removes your profile and active sessions. Support audit references may be retained without your profile details.</p><form id="delete-form"><label>Confirm your password<input name="password" type="password" required autocomplete="current-password"></label><p class="form-error" role="alert"></p><button class="btn danger" type="submit">Permanently delete account</button></form>');break;}}catch(err){toast(err.message);}});
const csv=v=>'"'+String(v).replaceAll('"','""')+'"';function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,values=Object.fromEntries(new FormData(form)),submit=form.querySelector('button[type="submit"],button:not([type])');if(submit)submit.disabled=true;try{if(form.id==='auth-form'){const register=form.dataset.register==='true';const result=await api(register?'register':'login',values);user=result.user;demo=null;localStorage.removeItem('gs-demo');go(user.role==='admin'?'admin':'dashboard');toast(register?'Welcome to Glorysake. Make yourself at home.':'Good to have you back.');}if(form.id==='support-form'){const r=await api('support',values);form.reset();toast('Message received. Your reference: '+r.id);openModal(`<h2 id="modal-title">Your message is in.</h2><p>Keep this reference for follow-up:</p><strong>${esc(r.id)}</strong><p>Your request is now in the operations support queue.</p><button class="btn primary" data-action="close">Got it</button>`);}if(form.id==='settings-form'){if(demo){demo.name=values.name.trim();demo.country=values.country;save();}else user=(await api('account',values,'PATCH')).user;render(false);toast('Your details are updated.');}if(form.id==='practice-form'){if(!demo.pending.some(t=>t.id===playing.id)&&!demo.completed.includes(playing.id)){demo.pending.push({id:playing.id,name:playing.short,reward:playing.reward,submitted:new Date().toISOString()});save();}openModal('<span class="result-art">✳</span><h2 id="modal-title">A little effort, recorded.</h2><p>Your practice submission is saved as pending review on this device. No cash has been earned or promised.</p><button class="btn primary" data-action="close">Back to exploring</button>');render(false);}if(form.id==='campaign-form'){await api('admin/campaigns',values);await render(false);toast('Campaign draft saved.');}if(form.id==='delete-form'){await api('account',{password:values.password},'DELETE');user=null;$('#modal').close();go('');toast('Account deleted.');}}catch(err){const error=form.querySelector('.form-error');if(error)error.textContent=err.message;else toast(err.message);}finally{if(submit)submit.disabled=false;}});
if(staticMode){render();}else{api('session').then(r=>{user=r.user;render(false);}).catch(()=>render(false));}
